<?php require 'config.php';require_login();$s=$pdo->prepare('SELECT b.*,f.airline,f.flight_no,f.origin,f.destination,f.departure,f.arrival FROM bookings b JOIN flights f ON f.id=b.flight_id WHERE b.id=? AND b.user_id=?');$s->execute([(int)$_GET['id'],$_SESSION['user_id']]);$b=$s->fetch();if(!$b)exit('Ticket not found');?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card" id="ticket"><h1>✈ E-Ticket</h1><h2><?=h($b['airline'])?> · <?=h($b['flight_no'])?></h2><p><b>Booking code:</b> <?=h($b['booking_code'])?></p><p><b>Passenger:</b> <?=h($b['passenger_name'])?> (<?=h($b['passenger_age'])?>)</p><p><b>Route:</b> <?=h($b['origin'])?> → <?=h($b['destination'])?></p><p><b>Departure:</b> <?=h($b['departure'])?></p><p><b>Arrival:</b> <?=h($b['arrival'])?></p><p><b>Seat:</b> <?=h($b['seat_no'])?> | <b>Status:</b> <?=h($b['status'])?></p><button onclick="window.print()">Print ticket</button></div></div></body></html>